"""Carga 5 (ampliação, 2026-09-29): itens extras de FAQ de preparo, pesquisados por agentes e filtrados pelas regras do projeto."""
ITENS = [
    ('Citologia oncótica (Papanicolau)', 'Posso usar absorvente interno antes do Papanicolau?', 'O ideal é evitar absorvente interno no período indicado no seu preparo, junto com duchas, cremes e medicamentos vaginais. Esses produtos podem alterar a coleta e dificultar a leitura das células no laboratório. Se usou sem querer, avise a equipe da clínica.', ('Saudelab - Preparo para Papanicolau', 'https://saudelab.com/preparo-para-exame-papanicolau/')),
    ('Citologia oncótica (Papanicolau)', 'Como devo fazer a higiene íntima antes do Papanicolau?', 'Pode tomar banho normalmente, usando apenas água e sabonete suave na região íntima. Evite produtos muito perfumados ou antibacterianos, que podem irritar a mucosa. Não faça ducha vaginal.', ('Terra - Preparo para Papanicolau: 10 coisas', 'https://www.terra.com.br/vida-e-estilo/saude/preparo-para-exame-papanicolau-10-coisas-que-voce-precisa-saber,3500a42c18b44f7416eaf01092624ab5z8heutyn.html')),
    ('Citologia oncótica (Papanicolau)', 'Preciso me depilar para fazer o Papanicolau?', 'Não. A depilação é uma escolha pessoal e não interfere no resultado do exame. Os profissionais estão acostumados com todo tipo de corpo e o foco é só a sua saúde.', ('Saudelab - Preparo para Papanicolau', 'https://saudelab.com/preparo-para-exame-papanicolau/')),
    ('Citologia oncótica (Papanicolau)', 'Que roupa é melhor usar no dia do Papanicolau?', 'Roupas confortáveis e práticas, como vestido, saia ou calça leve, ajudam a deixar o momento mais tranquilo. Você vai precisar tirar a roupa da cintura para baixo na sala de coleta, então escolha algo que facilite.', ('Terra - Preparo para Papanicolau: 10 coisas', 'https://www.terra.com.br/vida-e-estilo/saude/preparo-para-exame-papanicolau-10-coisas-que-voce-precisa-saber,3500a42c18b44f7416eaf01092624ab5z8heutyn.html')),
    ('Citologia oncótica (Papanicolau)', 'O Papanicolau dói?', 'Em geral é rápido e indolor, podendo causar só uma pressão ou um leve desconforto quando o espéculo é colocado. O incômodo costuma durar poucos segundos. Se sentir dor, avise a pessoa que faz a coleta para ela ajustar o movimento.', ('Padrão - Dúvidas sobre o exame de Papanicolau', 'https://www.padrao.com.br/blog/exame-de-papanicolau')),
    ('Citologia oncótica (Papanicolau)', 'Quanto tempo dura a coleta do Papanicolau?', 'A coleta é rápida e leva poucos minutos. Com a espátula e a pequena escova, a equipe retira células do colo do útero e envia para análise no laboratório.', ('Vale Saúde - Papanicolau', 'https://www.valesaude.com.br/exames/papanicolau/')),
    ('Citologia oncótica (Papanicolau)', 'Grávida pode fazer o Papanicolau?', 'Pode, e o exame é considerado seguro para a mãe e para o bebê, pois não atinge o interior do útero. A equipe indica em qual fase da gestação a coleta é mais adequada. Avise sempre que estiver grávida ou com suspeita de gravidez.', ('Vale Saúde - Papanicolau', 'https://www.valesaude.com.br/exames/papanicolau/')),
    ('Citologia oncótica (Papanicolau)', 'Depois do Papanicolau, é normal sangrar um pouco?', 'Sim, pode haver um sangramento leve e algumas cólicas passageiras logo após a coleta. Isso costuma passar ao longo do dia. Se o sangramento for forte ou não parar, procure atendimento.', ('Padrão - Dúvidas sobre o exame de Papanicolau', 'https://www.padrao.com.br/blog/exame-de-papanicolau')),
    ('Citologia oncótica (Papanicolau)', 'Posso voltar à rotina normal depois do Papanicolau?', 'Sim, você pode voltar às suas atividades normalmente. Alguns roteiros de preparo pedem para evitar relação sexual, absorvente interno e esforço físico intenso logo após a coleta, então siga o que estiver no seu preparo.', ('Vale Saúde - Papanicolau', 'https://www.valesaude.com.br/exames/papanicolau/')),
    ('Citologia oncótica (Papanicolau)', 'Se o resultado vier alterado, significa que estou com câncer?', 'Não necessariamente. Um resultado alterado pode estar ligado a inflamações, infecções, alterações relacionadas ao HPV ou pequenas lesões. O objetivo do exame é justamente identificar mudanças cedo, e a equipe orienta os próximos passos.', ('Terra - Preparo para Papanicolau: 10 coisas', 'https://www.terra.com.br/vida-e-estilo/saude/preparo-para-exame-papanicolau-10-coisas-que-voce-precisa-saber,3500a42c18b44f7416eaf01092624ab5z8heutyn.html')),
    ('Citologia oncótica (Papanicolau)', 'Preciso fazer o Papanicolau mesmo sem sintomas?', 'Sim. O exame é preventivo e serve justamente para quem não sente nada. Ele costuma ser indicado para quem já iniciou a vida sexual, seguindo a periodicidade que a equipe de saúde orientar.', ('Terra - Preparo para Papanicolau: 10 coisas', 'https://www.terra.com.br/vida-e-estilo/saude/preparo-para-exame-papanicolau-10-coisas-que-voce-precisa-saber,3500a42c18b44f7416eaf01092624ab5z8heutyn.html')),
    ('Citologia oncótica (Papanicolau)', 'Por que preciso evitar relação sexual antes do exame?', 'Resíduos de esperma, lubrificantes e outras substâncias podem se misturar às células do colo do útero e atrapalhar a análise. Por isso vale cumprir o período indicado no seu preparo.', ('CitClinLab - Papanicolau: guia completo', 'https://citclinlab.com.br/papanicolau-guia-completo-sobre-o-exame-preventivo/')),
    ('Citologia oncótica (Papanicolau)', 'Tive relação sexual pouco antes do Papanicolau. E agora?', 'Avise a equipe antes da coleta. Dependendo do caso, a amostra pode ficar prejudicada e pode ser necessário repetir o exame ou remarcar.', ('Vale Saúde - Papanicolau', 'https://www.valesaude.com.br/exames/papanicolau/')),
    ('Citologia oncótica (Papanicolau)', 'Posso fazer o Papanicolau e o ultrassom transvaginal no mesmo dia?', 'Sim, é possível fazer os dois exames no mesmo dia. Informe ao agendar para a clínica organizar a ordem e os cuidados de cada exame.', ('CitClinLab - Papanicolau: guia completo', 'https://citclinlab.com.br/papanicolau-guia-completo-sobre-o-exame-preventivo/')),
    ('Citologia oncótica (Papanicolau)', 'O Papanicolau detecta gravidez?', 'Não. O exame avalia as células do colo do útero e a saúde dessa região, e não serve para saber se há gravidez.', ('CitClinLab - Papanicolau: guia completo', 'https://citclinlab.com.br/papanicolau-guia-completo-sobre-o-exame-preventivo/')),
    ('Citologia oncótica (Papanicolau)', 'Preciso levar pedido para fazer o Papanicolau?', 'Sim, em geral é necessário levar o pedido de exame. Leve também documento com foto e, se tiver, resultados de exames anteriores.', ('CitClinLab - Papanicolau: guia completo', 'https://citclinlab.com.br/papanicolau-guia-completo-sobre-o-exame-preventivo/')),
    ('Citologia oncótica (Papanicolau)', 'Estou nervosa ou com vergonha do exame. O que posso fazer?', 'É muito comum se sentir assim. Conte à pessoa que fará a coleta, pois ela pode explicar cada passo e ir com mais calma. Respirar fundo e relaxar a musculatura ajuda a reduzir o desconforto.', ('Saudelab - Preparo para Papanicolau', 'https://saudelab.com/preparo-para-exame-papanicolau/')),
    ('Citologia oncótica (Papanicolau)', 'Estou na menopausa ou sinto a vagina seca. O exame incomoda mais?', 'Pode incomodar um pouco mais, pois a região fica mais sensível e ressecada. Avise a equipe antes de começar para que o material seja colocado com mais cuidado.', ('Padrão - Dúvidas sobre o exame de Papanicolau', 'https://www.padrao.com.br/blog/exame-de-papanicolau')),
    ('Citologia oncótica (Papanicolau)', 'Se estiver com uma infecção ou corrimento, posso fazer o exame?', 'Avise a equipe da clínica. Em infecções agudas, o exame pode ser adiado para a coleta ficar mais confiável, e a equipe decide o melhor momento.', ('CitClinLab - Papanicolau: guia completo', 'https://citclinlab.com.br/papanicolau-guia-completo-sobre-o-exame-preventivo/')),
]
